package com.bookstore.order.entity;
import com.bookstore.book.entity.Book; import com.fasterxml.jackson.annotation.JsonIgnore; import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="order_items") public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id",nullable=false) private Order order; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="book_id",nullable=false) private Book book; @Column(nullable=false) private Integer quantity; @Column(name="unit_price",nullable=false,precision=12,scale=2) private BigDecimal unitPrice; public void setOrder(Order v){order=v;} public Book getBook(){return book;} public void setBook(Book v){book=v;} public Integer getQuantity(){return quantity;} public void setQuantity(Integer v){quantity=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} }
